from pathlib import Path
import json,re
ROOT=Path(__file__).resolve().parents[1]
MAN=json.loads((ROOT/'release-manifest-v0.64.1.json').read_text())
REG=json.loads((ROOT/'registry/workspace-product-record-v0.64.1.json').read_text())
MAIN=(ROOT/'wordpress/sustainable-catalyst-workspace/sustainable-catalyst-workspace.php').read_text()
PHP=(ROOT/'wordpress/sustainable-catalyst-workspace/includes/class-sc-workspace.php').read_text()
REGPHP=(ROOT/'wordpress/sustainable-catalyst-workspace/includes/class-sc-workspace-registry.php').read_text()
APP=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/workspace-v0.64.1.js').read_text()
CSS=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/css/workspace-v0.64.1.css').read_text()
COMPAT=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-browser-compatibility-v1.js').read_text()
A11Y=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-accessibility-v1.js').read_text()
INTEGRITY=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-persistence-integrity-v1.js').read_text()
def check(ok,label):
    if not ok: raise SystemExit('FAIL - '+label)
check('Version: 0.64.1' in MAIN and "SC_WORKSPACE_VERSION', '0.64.1" in MAIN,'plugin version')
check((MAN['version'],MAN['previous_version'],MAN['release_name'])==('0.64.1','0.64.0','Accessibility Runtime & Desktop Layout Recovery'),'release lineage')
check(MAN['storage_schema_version']==35 and MAN['project_schema']=='sc-workspace-project/20.0' and MAN['schema_migration_required'] is False,'schema stable')
block=re.search(r"wp_enqueue_script\(\s*'sc-workspace-accessibility-v1'.*?\n\s*\);",PHP,re.S)
check(bool(block),'accessibility enqueue found')
check("array('sc-workspace-browser-compatibility-v1')" in block.group(0) and "array('sc-workspace-browser-compatibility-v1', 'sc-workspace-accessibility-v1')" not in block.group(0),'accessibility self dependency removed')
check('workspace-v0.64.1.js' in PHP and 'workspace-v0.64.1.css' in PHP and "'sc-workspace-v0641'" in PHP and len(APP)>100000,'current assets')
check('.scw-platform-hero-grid{grid-template-columns:minmax(0,1.18fr) minmax(0,.82fr)}' in CSS,'hero track hardening')
check('.scw-research-overview{grid-template-columns:minmax(0,1.05fr) minmax(0,.95fr)}' in CSS,'research track hardening')
check('.scw-platform-hero-grid>*' in CSS and '.scw-research-overview>*' in CSS and 'min-width:0;max-width:100%' in CSS,'grid child minimum hardening')
check(MAN['runtime_layout_recovery']['viewports']==[1600,1440,1280,1024,768,390] and MAN['runtime_layout_recovery']['full_wordpress_footer_render_manual_qa'] is True,'viewport regression boundary')
check("SCHEMA='sc-workspace-accessibility/1.0'" in A11Y and "const TARGET='WCAG 2.2 AA'" in A11Y and 'automatedCertification:false' in A11Y,'v0.64 accessibility preserved')
check("SCHEMA='sc-workspace-browser-compatibility/1.0'" in COMPAT and 'featureDetectionPrimary:true' in COMPAT,'v0.63 compatibility preserved')
check("METADATA_KEY='sc_workspace_persistence_integrity_v0620'" in INTEGRITY,'v0.62 persistence integrity preserved')
check("BACKUP_KEY = 'sc_workspace_registry_backup_v0641'" in REGPHP and 'LEGACY_PENDING_KEY_V0640' in REGPHP,'registry recovery')
check(REG['public_version']=='0.64.1' and REG['previous_version']=='0.64.0' and REG['release_name']=='Accessibility Runtime & Desktop Layout Recovery','registry record')
check((ROOT/'history/release-manifest-v0.64.0.json').exists() and (ROOT/'history/workspace-product-record-v0.64.0.json').exists(),'predecessor history')
print('PASS - v0.64.1 release validator')
